      "mean_CAR": 0.764,
      "std_CAR": null,
      "status": "1seed_complete_1running"
    },
    {
      "condition": "Full_OCC",
      "gradient_flow_steps": 50000,
      "description": "Full OCC with gradient flow throughout (occ_detach=False, BN)",
      "seeds": {
        "s0": {"CAR": 0.832, "TSR": 0.904, "exp_id": "mvp_occ_s0"},
        "s1": {"CAR": 0.788, "TSR": 0.938, "exp_id": "occ_s1_fresh"},
