        "s0": {"CAR": 0.700, "TSR": 0.788, "exp_id": "reverse_cutoff_s0_eval"},
        "s1": {"CAR": 0.736, "TSR": 0.890, "exp_id": "reverse_cutoff_s1_eval"},
